import {advanceCareerTime} from './career-systems.mjs';
const DAY=86400000;
export function dayNumber(iso){if(!/^\d{4}-\d{2}-\d{2}$/.test(iso||''))throw Error('Choose a valid calendar date.');const n=Date.parse(iso+'T00:00:00Z');if(!Number.isFinite(n)||new Date(n).toISOString().slice(0,10)!==iso)throw Error('Choose a valid calendar date.');return n/DAY;}
export const addDays=(date,n)=>new Date((dayNumber(date)+n)*DAY).toISOString().slice(0,10);
export function seasonAnchor(year){const d=new Date(Date.UTC(year,8,1)),offset=(8-d.getUTCDay())%7;return new Date(d.getTime()+offset*DAY).toISOString().slice(0,10);}
export function leagueDates(season,scheduleLength=18){const year=season+1,march=new Date(Date.UTC(year,2,1)),monday=1+(8-march.getUTCDay())%7+7,april=new Date(Date.UTC(year,3,30)),lastThursday=30-(april.getUTCDay()+3)%7;return{tampering:`${year}-03-${String(monday).padStart(2,'0')}`,freeAgency:`${year}-03-${String(monday+2).padStart(2,'0')}`,draft:`${year}-04-${String(lastThursday).padStart(2,'0')}`,camp:`${year}-07-28`,opener:addDays(seasonAnchor(year),6),championship:addDays(seasonAnchor(season),(scheduleLength-1)*7+6+35)};}
export function ensureCalendar(s){const f=s.franchise;if(!f.calendarSim){const anchor=seasonAnchor(s.year),lastRegular=addDays(anchor,(s.schedule.length-1)*7+6),round=f.postseason?.round||0,off=leagueDates(s.year,s.schedule.length);let date=s.phase==='season'?addDays(anchor,s.week*7):s.phase==='playoffs'?addDays(lastRegular,1+round*7):addDays(off.championship,1);f.calendarSim={version:1,date,nextRoundDate:s.phase==='season'?addDays(anchor,s.week*7+6):s.phase==='playoffs'?addDays(lastRegular,(round+1)*7+(round>=3?7:0)):null,completed:[],events:[],session:null,offseasonDays:{}};}return f.calendarSim;}
export function advanceDate(s,date){const c=ensureCalendar(s),days=dayNumber(date)-dayNumber(c.date);if(days<0)throw Error('The calendar cannot move backward.');if(days===0)return 0;c.date=date;advanceCareerTime(s,days,'date:'+date);return days;}
export function settleCalendarRound(s,info){const c=ensureCalendar(s);if(c.completed.includes(info.key))return;const matchDate=c.nextRoundDate||c.date;advanceDate(s,matchDate);c.events.unshift({id:info.key,date:c.date,kind:info.phase==='playoffs'?'Playoff round':'League round',year:s.year,week:info.week,round:info.round,status:'Completed'});c.events=c.events.slice(0,180);c.completed.push(info.key);c.completed=c.completed.slice(-180);c.nextRoundDate=addDays(c.date,info.phase==='playoffs'&&info.round===2?14:7);}
export function enterOffseasonCalendar(s){const c=ensureCalendar(s);c.nextRoundDate=null;}
export function enterSeasonCalendar(s){const c=ensureCalendar(s),camp=`${s.year}-07-28`,anchor=seasonAnchor(s.year);if(c.date<camp)advanceDate(s,camp);c.nextRoundDate=addDays(anchor,6);c.events.unshift({id:'camp-'+s.year,date:c.date,kind:'Training camp',status:'Completed'});}
export function marketCalendarDate(s){const c=ensureCalendar(s),dates=leagueDates(s.year,s.schedule.length);const next=s.phase==='offseason'&&c.date<dates.tampering?dates.tampering:addDays(c.date,1);if(s.phase!=='offseason'&&c.nextRoundDate&&next>c.nextRoundDate)throw Error('Play the scheduled round before advancing the market.');advanceDate(s,next);}
export function validateTargetDate(s,target){const c=ensureCalendar(s),n=dayNumber(target)-dayNumber(c.date);if(n<=0)throw Error('Choose a date after today.');if(n>730)throw Error('Simulate up to two years at a time.');if(s.live&&!s.live.finished)throw Error('Finish or quick-sim the live game before starting a calendar holiday.');return target;}
export function monthDays(month){const first=month+'-01',d=new Date(dayNumber(first)*DAY),offset=(d.getUTCDay()+6)%7;return Array.from({length:42},(_,i)=>addDays(first,i-offset));}
export function eventsOn(s,date){const c=ensureCalendar(s),events=c.events.filter(e=>e.date===date);const anchor=seasonAnchor(s.year);if(s.phase==='season')s.schedule.forEach((round,w)=>{const game=round.find(g=>g.a===s.team||g.b===s.team);if(addDays(anchor,w*7+6)===date)events.push({kind:game?'Matchday':'Bye week',game,week:w,status:game?.score?'Completed':'Scheduled'});});if(s.phase==='playoffs'&&date===c.nextRoundDate)events.push({kind:['Wild Card','Divisional','Conference championship','Championship'][s.franchise.postseason?.round||0],game:s.playoffs?.rounds.at(-1)?.find(g=>g.a===s.team||g.b===s.team),status:'Scheduled'});const dates=leagueDates(s.year,s.schedule.length);for(const[k,label]of Object.entries({tampering:'Legal tampering opens',freeAgency:'Free agency opens',draft:'NFL Draft',camp:'Training camp',opener:'Opening Sunday'}))if(dates[k]===date)events.push({kind:label,status:'Scheduled'});return events;}
